{
  "objectives": [
    {
      "level": "primary",
      "text": "Estimate the ORR for metastatic BCC (Group 1) or unresectable locally advanced BCC (Group 2), according to central review, when treated with cemiplimab monotherapy in patients who have progressed on HHI therapy, or were intolerant of prior HHI therapy.",
      "quote": "The primary objective of the study is to estimate the ORR for metastatic BCC (Group 1) or unresectable locally advanced BCC (Group 2), according to central review, when treated with cemiplimab monotherapy in patients who have progressed on HHI therapy, or were intolerant of prior HHI therapy",
      "endpoints": [
        {
          "text": "Overall response rate (ORR) as determined by central review, assessed separately for Group 1 and Group 2.",
          "measure": "ORR",
          "timepoints_weeks": [],
          "quote": "The primary efficacy endpoint for this study is the ORR as determined by central review."
        }
      ]
    },
    {
      "level": "secondary",
      "text": "Assess secondary objectives for both Group 1 and Group 2: investigator review, overall survival (OS), impact on quality of life using EORTC QLQ-C30 and Skindex-16.",
      "quote": "The secondary objectives for both Group 1 and Group 2 are to: investigator review, and overall survival (OS) • Assess the impact of cemiplimab on quality of life using European Organisation for Research and Treatment of Cancer Quality of Life Questionnaire Core 30 (EORTC QLQ-C30) and Skindex-16",
      "endpoints": [
        {
          "text": "Duration of response",
          "measure": "Duration of response",
          "timepoints_weeks": [],
          "quote": "Duration of response"
        },
        {
          "text": "Progression-free survival (PFS)",
          "measure": "PFS",
          "timepoints_weeks": [],
          "quote": "PFS"
        },
        {
          "text": "Overall survival (OS)",
          "measure": "OS",
          "timepoints_weeks": [],
          "quote": "OS"
        },
        {
          "text": "Complete response (CR) rate",
          "measure": "CR rate",
          "timepoints_weeks": [],
          "quote": "CR rate"
        },
        {
          "text": "Change in scores of patient-reported outcomes in the EORTC QLQ-C30 and the Skindex-16",
          "measure": "Change in scores of patient-reported outcomes",
          "timepoints_weeks": [],
          "quote": "Change in scores of patient-reported outcomes in the EORTC QLQ-C30 and the Skindex-16"
        },
        {
          "text": "Adverse events (AEs)",
          "measure": "AEs",
          "timepoints_weeks": [],
          "quote": "AEs"
        },
        {
          "text": "Concentrations of cemiplimab in serum (at select sites)",
          "measure": "Concentrations of cemiplimab in serum",
          "timepoints_weeks": [],
          "quote": "Concentrations of cemiplimab in serum (at select sites)"
        },
        {
          "text": "Anti-cemiplimab antibodies",
          "measure": "Anti-cemiplimab antibodies",
          "timepoints_weeks": [],
          "quote": "Anti-cemiplimab antibodies"
        }
      ]
    },
    {
      "level": "exploratory",
      "text": "Explore pharmacodynamic effects of cemiplimab in tumor biopsies obtained at baseline, during treatment, and at progression in BCC patients, and assess predictive potential and correlation to clinical response for biomarkers of interest.",
      "quote": "The exploratory objectives (for Group 2 only) are to explore the pharmacodynamic effects of cemiplimab in tumor biopsies obtained at baseline, during treatment, and at progression in BCC patients treated with cemiplimab, and to assess predictive potential and correlation to clinical response for biomarkers of interest",
      "endpoints": [
        {
          "text": "Associations between tumor non-synonymous mutational burden at baseline and efficacy",
          "measure": "Associations between tumor non-synonymous mutational burden and efficacy",
          "timepoints_weeks": [],
          "quote": "Associations between tumor non-synonymous mutational burden at baseline and efficacy"
        },
        {
          "text": "Pharmacodynamic changes comparing baseline and on-treatment biopsies: changes in tumor mRNA expression, changes in number of TILs and distribution, changes in expression levels of PD-L1, GITR, LAG-3, and other check-point modulators, changes in number and type of genetic mutations.",
          "measure": "Pharmacodynamic changes in tumor biopsies",
          "timepoints_weeks": [],
          "quote": "Pharmacodynamic changes, comparing baseline and on-treatment biopsies: - Changes in tumor mRNA expression - Changes in number of TILs (CD8+ T cells, CD4+ T cells, T regulatory cells, and tissue permitting, other subtypes such as B cells, myeloid-derived cells, NK cells, etc.) and descriptive change in distribution of TILs in respect to tumor tissue and stroma - Change in expression levels (mRNA and/or protein) of PD-L1, GITR, and LAG-3, and possibly other check-point modulators - Change in number and type of genetic mutations in known oncogenes and potential tumor neoantigens"
        }
      ]
    }
  ]
}
